          text: '1830年、フランスで七月革命がおこり、銀行家などに支持された立憲王政が成立した。1832年にはイギリスで第1回選挙法改正が行われ、産業資本家などの中産階級が選挙権を得た。',
          talk: '1830年7月、パリの市民はバリケードを築き、言論をおさえようとした国王を3日間で追い出しました。七月革命です。この知らせは各地の自由主義者を勇気づけます。イギリスでは、1832年に選挙法が改正され、工場の経営者など、新しくお金持ちになった人々が選挙権を手に入れました。ただし、労働者や女性にはまだ選挙権がありません。この時代の自由主義は、まず財産をもつ人々の自由だったのです。',
          place: 'パリ', lon: 2.35, lat: 48.86, span: 8,
