          talk: '1848年は「諸国民の春」とよばれます。2月にパリで革命がおこると、3月にはウィーンとベルリンでも民衆が立ち上がりました。30年以上ヨーロッパを押さえてきたメッテルニヒは、変装してイギリスへ逃げたと伝えられます。ドイツ各地の代表はフランクフルトに集まり、自由と統一の憲法をつくろうとしました。この革命の多くは結局おさえこまれましたが、憲法や議会は、その後の各国で少しずつ当たり前のものになっていきます。',
