          talk: '西アフリカの海岸には、ヨーロッパの国々がとりでを築きました。ガーナのエルミナ城もその一つです。商人は銃や布、ラム酒をもちこみ、アフリカの勢力から捕らえられた人々を買いました。人々は船の底に、身動きもできないほどぎっしりと横たえられ、1〜2か月かけて大西洋をわたります。これを中間航路といいます。不衛生な船の中で、運ばれた人の1割以上が途中で亡くなったと考えられています。',
