          talk: 'カリブ海の島々は、砂糖の島でした。サトウキビを刈り、すぐに煮つめて砂糖にする仕事は、昼も夜も続く重労働です。奴隷とされた人々は、自由も家族と暮らす権利も奪われ、多くが若くして亡くなりました。その砂糖はヨーロッパへ運ばれ、紅茶やお菓子に使われます。イギリスの家庭の甘い一杯は、遠い島の苦しみとつながっていたのです。運ばれた人の数は、全体で1000万人をこえると推計されています。',
