          talk: '奴隷とされた人々は、ただ耐えていたわけではありません。1791年、フランスの植民地サン=ドマングで、奴隷たちが一斉に立ち上がりました。元奴隷のトゥサン=ルヴェルチュールが指導者となり、ナポレオンが送った軍とも戦います。トゥサン自身は捕らえられてフランスで亡くなりますが、1804年、ハイチは独立を宣言しました。奴隷が自らの力で国をつくった、世界で初めての例です。',
