          talk: '4世紀から5世紀、華北では遊牧民の王朝が次々に興っては滅び、戦乱が続きました。村は焼かれ、畑は荒れ放題です。生きのびた農民は、地元の豪族の屋敷にかけこみ、守ってもらうかわりにその小作人になりました。すると国は、農民がどこに何人いるのかつかめず、税も兵士も集められません。華北を統一した北魏にとって、農民をどう取りもどすかが大きな課題でした。',
